import { Injectable } from '@angular/core';
import { CanDeactivate } from '@angular/router';

/**
 * A screen that holds work worth warning about before it is navigated away from.
 */
export interface HasUnsavedChanges {
  /** True when it is safe to leave — nothing entered, or already saved. */
  canLeave(): boolean;
  /** Text shown in the confirmation, so each screen can name what is at stake. */
  unsavedChangesMessage?(): string;
}

const DEFAULT_MESSAGE =
  'You have unsaved changes on this page. Leave and discard them?';

/**
 * Blocks navigation out of a form that still holds unsaved input.
 *
 * Long admin forms are easy to lose to a mis-clicked "Back to List", and none of
 * this data is recoverable once the component is torn down.
 */
@Injectable({
  providedIn: 'root',
})
export class UnsavedChangesGuard implements CanDeactivate<HasUnsavedChanges> {
  canDeactivate(component: HasUnsavedChanges): boolean {
    // A route can outlive its component during teardown; nothing to protect then.
    if (!component || typeof component.canLeave !== 'function') {
      return true;
    }

    if (component.canLeave()) {
      return true;
    }

    const message = component.unsavedChangesMessage
      ? component.unsavedChangesMessage()
      : DEFAULT_MESSAGE;

    return confirm(message);
  }
}
