import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { CommonService } from 'src/app/shared/services/common.service';
import { CategoryService } from 'src/app/shared/services/category.service';

@Component({
  selector: 'app-faq-list',
  templateUrl: './faq-list.component.html',
  styleUrls: ['./faq-list.component.css'],
})
export class FaqListComponent implements OnInit {

  displayData: any[] = [];

  pageIndex = 1;
  pageSize = 10;
  total = 0;

  searchInput = '';
  selectedCategory: string | null = null;
  categories: any[] = [];

  constructor(
    private commonService: CommonService,
    private categoryService: CategoryService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.loadCategories();
    this.fetchData();
  }

  /* ---------- LOAD CATEGORIES ---------- */
  loadCategories(): void {
    this.categoryService.getActiveCategories().subscribe({
      next: (res: any) => {
        this.categories = res.result.categories;
      },
      error: (err) => {
        console.error('Error fetching categories:', err);
      },
    });
  }

  /* ---------- FETCH DATA ---------- */
  fetchData(): void {
    const paramsObj: any = {};

    if (this.searchInput) {
      paramsObj.search = this.searchInput;
    }
    if (this.selectedCategory) {
      paramsObj.category = this.selectedCategory;
    }

    this.commonService
      .getData(this.pageIndex, this.pageSize, 'faq/adminAll', paramsObj)
      .subscribe({
        next: (res: any) => {
          this.displayData = res.result.faqs;
          this.total = res.result.totalCount;
        },
        error: (err) => {
          console.error('Error fetching FAQs:', err);
        },
      });
  }

  /* ---------- SEARCH / FILTER ---------- */
  search(): void {
    this.pageIndex = 1;
    this.fetchData();
  }

  onCategoryChange(): void {
    this.pageIndex = 1;
    this.fetchData();
  }

  /* ---------- DELETE ---------- */
  deleteItem(id: string): void {
    if (!confirm('Are you sure you want to delete this FAQ?')) return;

    this.commonService.deleteItem('/faq', id).subscribe({
      next: () => {
        alert('FAQ deleted successfully');
        this.fetchData();
      },
      error: (err) => {
        alert(err?.error?.message || 'Failed to delete FAQ');
      },
    });
  }

  /* ---------- PAGINATION ---------- */
  onPageChange(page: number): void {
    this.pageIndex = page;
    this.fetchData();
  }
}
