import { Injectable } from '@angular/core';
import { HttpClient, HttpEventType, HttpHeaders, HttpResponse } from '@angular/common/http';
import { Observable } from 'rxjs';
import { filter, map, tap } from 'rxjs/operators';
import { environment } from 'src/environments/environment';

/** Outcome of a client-side file check, before anything is sent. */
export interface FileValidation {
  valid: boolean;
  error: string | null;
}

@Injectable({
  providedIn: 'root',
})
export class FileUploadService {
  constructor(private http: HttpClient) {}

  private allowedTypes = [
    'application/pdf',
    'image/jpeg',
    'image/jpg',
    'image/png',
    'image/webp',
    'image/svg+xml',
    'image/gif',
    'image/bmp',
    'image/tiff',
    'image/heic',
    'image/heif',
    'image/avif',
    'image/x-icon',
  ];
  private maxFileSize = 4 * 1024 * 1024; // 4 MB

  private allowedVideoTypes = [
    'video/mp4',
    'video/webm',
    'video/quicktime',
    'video/x-m4v',
  ];
  /**
   * Ceiling for video. Larger than the image cap because a short clay-type clip
   * will not fit in 4 MB — adjust to match whatever the upload endpoint accepts.
   */
  private maxVideoSize = 50 * 1024 * 1024; // 50 MB

  validateImageFile(file: File): FileValidation {
    // Check file type
    if (!this.allowedTypes.includes(file.type)) {
      return {
        valid: false,
        error:
          'Only PDF, JPEG, JPG, PNG, WEBP, SVG, GIF, BMP, TIFF, HEIC, HEIF, AVIF, and ICO files are allowed.',
      };
    }

    // Check file size
    if (file.size > this.maxFileSize) {
      return { valid: false, error: 'File size should not exceed 4 MB.' };
    }

    return { valid: true, error: null };
  }

  /**
   * Same intent as validateImageFile, for the fields that also take video
   * (the workshop banner and the per-option clay-type clip). Video gets its own
   * ceiling; anything that is not a video falls through to the image rules so
   * the two paths cannot drift apart.
   */
  validateMediaFile(file: File, allowVideo: boolean = true): FileValidation {
    const isVideo = file.type.startsWith('video/');

    if (!isVideo) {
      return this.validateImageFile(file);
    }

    if (!allowVideo) {
      return { valid: false, error: 'This field takes an image, not a video.' };
    }

    if (!this.allowedVideoTypes.includes(file.type)) {
      return {
        valid: false,
        error: 'Only MP4, WEBM, MOV and M4V video files are allowed.',
      };
    }

    if (file.size > this.maxVideoSize) {
      return {
        valid: false,
        error: `Video size should not exceed ${this.maxVideoSize / (1024 * 1024)} MB.`,
      };
    }

    return { valid: true, error: null };
  }

  /** Human-readable size, for messages that quote what the admin picked. */
  formatSize(bytes: number): string {
    if (bytes < 1024) {
      return `${bytes} B`;
    }
    if (bytes < 1024 * 1024) {
      return `${Math.round(bytes / 1024)} KB`;
    }
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  }

  /**
   * Uploads one or more files and resolves to the API's response body.
   *
   * Passing `onProgress` switches the request to event mode so the caller can
   * show byte-level progress; the stream is then narrowed back to the response
   * body, so both paths emit exactly the same value and existing callers that
   * omit it are unaffected.
   */
  uploadFileService(
    files: File[],
    location: string,
    watermark: boolean = false,
    onProgress?: (percent: number) => void,
  ): Observable<any> {
    const formData = new FormData();

    files.forEach((file) => formData.append('files', file));
    const currentUser = localStorage.getItem('currentUser');

    const token = currentUser ? JSON.parse(currentUser).token : null;
    const headers = new HttpHeaders({
      Authorization: `Bearer ${token}`,
    });

    const url = `${environment.baseUrl}/upload?location=${encodeURIComponent(
      location,
    )}&watermark=${watermark}`;

    if (!onProgress) {
      return this.http.post<any>(url, formData, { headers });
    }

    return this.http
      .post<any>(url, formData, {
        headers,
        reportProgress: true,
        observe: 'events',
      })
      .pipe(
        tap((event) => {
          if (event.type === HttpEventType.UploadProgress && event.total) {
            onProgress(Math.round((100 * event.loaded) / event.total));
          }
        }),
        filter((event): event is HttpResponse<any> => event.type === HttpEventType.Response),
        map((event) => event.body),
      );
  }
}
