import { Component, OnInit } from '@angular/core';
import { NzModalService } from 'ng-zorro-antd/modal';
import { NzNotificationService } from 'ng-zorro-antd/notification';
import { CommonService } from 'src/app/shared/services/common.service';
import { toLocalDateString } from 'src/app/shared/utils/date.util';
import {
  formatTime12,
  minutesOfDay,
  parseTimeString,
} from 'src/app/shared/utils/time.util';

/** A window the studio is unavailable, as stored by the API. */
interface BlockedTime {
  _id?: string;
  date: string;
  startTime?: string;
  endTime?: string;
  allSlots?: boolean;
  reason: string;
}

@Component({
  selector: 'app-blocked-times',
  templateUrl: './blocked-times.component.html',
  styleUrls: ['./blocked-times.component.css'],
})
export class BlockedTimesComponent implements OnInit {
  /**
   * The workshops' default slots, as one-click presets. Blocking one also
   * closes any event slot running at the same time — the API applies blocks
   * to every slot that overlaps them.
   */
  readonly presets = [
    { label: 'Slot 1 · 10:30 – 12:00', from: '10:30 AM', to: '12:00 PM' },
    { label: 'Slot 2 · 14:00 – 15:30', from: '2:00 PM', to: '3:30 PM' },
    { label: 'Slot 3 · 16:00 – 17:30', from: '4:00 PM', to: '5:30 PM' },
    { label: 'Slot 4 · 18:00 – 19:30', from: '6:00 PM', to: '7:30 PM' },
    { label: 'Slot 5 · 20:00 – 21:30', from: '8:00 PM', to: '9:30 PM' },
  ];

  readonly reasons = [
    'Booked at the studio',
    'Private hire',
    'Maintenance',
    'Instructor unavailable',
    'Studio closed',
  ];

  selectedDate: Date = new Date();
  startTime: Date | null = parseTimeString('10:30 AM');
  endTime: Date | null = parseTimeString('12:00 PM');
  allSlots = false;
  reason = this.reasons[0];

  /** Every block in the months currently loaded, keyed by YYYY-MM-DD. */
  blocksByDate: { [date: string]: BlockedTime[] } = {};

  loading = false;
  saving = false;
  loadError = '';
  formError = '';

  /** Past days cannot be blocked — bound straight into nz-date-picker. */
  readonly disabledDate = (current: Date): boolean => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return current < today;
  };

  constructor(
    private commonService: CommonService,
    private notification: NzNotificationService,
    private modal: NzModalService,
  ) {}

  ngOnInit(): void {
    this.loadMonth(this.selectedDate);
  }

  /* ================= LOADING ================= */

  /** Loads a window either side of the month shown, so the dots stay filled. */
  loadMonth(around: Date): void {
    const from = new Date(around.getFullYear(), around.getMonth() - 1, 1);
    const to = new Date(around.getFullYear(), around.getMonth() + 2, 0);

    this.loading = true;
    this.loadError = '';

    this.commonService
      .getAllData(
        `studio/blocked-times?from=${toLocalDateString(from)}&to=${toLocalDateString(to)}`,
      )
      .subscribe({
        next: (res: any) => {
          const list: BlockedTime[] = res?.result || [];
          const grouped: { [date: string]: BlockedTime[] } = {};

          list.forEach((item) => {
            const key = (item.date || '').slice(0, 10);
            if (!key) return;
            grouped[key] = grouped[key] || [];
            grouped[key].push(item);
          });

          Object.keys(grouped).forEach((key) =>
            grouped[key].sort(this.byStart),
          );
          this.blocksByDate = grouped;
          this.loading = false;
        },
        error: () => {
          // The form stays usable — only the existing-blocks view is degraded.
          this.loading = false;
          this.loadError =
            'Could not load existing blocks. Times shown may be incomplete.';
        },
      });
  }

  private byStart = (a: BlockedTime, b: BlockedTime): number => {
    if (a.allSlots) return -1;
    if (b.allSlots) return 1;
    return minutesOfDay(a.startTime || '') - minutesOfDay(b.startTime || '');
  };

  onPanelChange(event: { date: Date; mode: string }): void {
    if (event?.date) {
      this.loadMonth(event.date);
    }
  }

  /* ================= VIEW HELPERS ================= */

  get selectedKey(): string {
    return toLocalDateString(this.selectedDate);
  }

  get blocksForDate(): BlockedTime[] {
    return this.blocksByDate[this.selectedKey] || [];
  }

  /** Drives the marker under each calendar cell. */
  hasBlocks(date: Date): boolean {
    return (this.blocksByDate[toLocalDateString(date)] || []).length > 0;
  }

  describe(block: BlockedTime): string {
    return block.allSlots
      ? 'All slots'
      : `${block.startTime} – ${block.endTime}`;
  }

  isPreset(preset: { from: string; to: string }): boolean {
    if (this.allSlots) return false;
    return (
      formatTime12(this.startTime as Date) === preset.from &&
      formatTime12(this.endTime as Date) === preset.to
    );
  }

  applyPreset(preset: { from: string; to: string }): void {
    this.allSlots = false;
    this.startTime = parseTimeString(preset.from);
    this.endTime = parseTimeString(preset.to);
    this.formError = '';
  }

  toggleAllSlots(): void {
    this.allSlots = !this.allSlots;
    this.formError = '';
  }

  /* ================= SAVE ================= */

  submit(): void {
    if (this.saving) return;

    this.formError = '';

    const from = this.allSlots ? '' : formatTime12(this.startTime as Date);
    const to = this.allSlots ? '' : formatTime12(this.endTime as Date);

    if (!this.allSlots) {
      if (!from || !to) {
        this.formError = 'Enter a start and end time, or choose All slots.';
        return;
      }
      if (minutesOfDay(to) <= minutesOfDay(from)) {
        this.formError = 'End time must be after the start time.';
        return;
      }
    }

    const clash = this.findClash(from, to);
    if (clash) {
      this.formError =
        clash.allSlots || this.allSlots
          ? 'This date already has an all-slots block.'
          : `Overlaps a block already set for ${clash.startTime} – ${clash.endTime}.`;
      return;
    }

    const payload: BlockedTime = this.allSlots
      ? { date: this.selectedKey, allSlots: true, reason: this.reason }
      : {
          date: this.selectedKey,
          startTime: from,
          endTime: to,
          reason: this.reason,
        };

    this.saving = true;

    this.commonService.addData('studio/blocked-times', payload).subscribe({
      next: () => {
        this.saving = false;
        this.notification.success(
          'Blocked',
          `${this.allSlots ? 'All slots' : from + ' – ' + to} on ${this.selectedKey} will not be bookable.`,
        );
        this.loadMonth(this.selectedDate);
      },
      error: (err) => {
        this.saving = false;
        this.notification.error(
          'Error',
          err?.error?.message || 'Could not block this time. Please try again.',
        );
      },
    });
  }

  /** Client-side guard; the API should enforce the same rule. */
  private findClash(from: string, to: string): BlockedTime | undefined {
    return this.blocksForDate.find((block) => {
      if (block.allSlots || this.allSlots) {
        return true;
      }
      return (
        minutesOfDay(from) < minutesOfDay(block.endTime || '') &&
        minutesOfDay(to) > minutesOfDay(block.startTime || '')
      );
    });
  }

  remove(block: BlockedTime): void {
    this.modal.confirm({
      nzTitle: 'Remove this block?',
      nzContent: `${this.describe(block)} will become bookable again on the website.`,
      nzOkText: 'Remove',
      nzOkDanger: true,
      nzOnOk: () => this.runRemove(block),
    });
  }

  private runRemove(block: BlockedTime): void {
    if (!block._id) {
      this.notification.error(
        'Error',
        'This block has no id and cannot be removed.',
      );
      return;
    }

    this.commonService
      .deleteItem('/studio/blocked-times', block._id)
      .subscribe({
        next: () => {
          this.notification.success('Removed', 'That time is bookable again.');
          this.loadMonth(this.selectedDate);
        },
        error: (err) => {
          this.notification.error(
            'Error',
            err?.error?.message || 'Could not remove this block.',
          );
        },
      });
  }
}
