/**
 * Formats a date as YYYY-MM-DD in the browser's own timezone.
 *
 * `toISOString()` converts to UTC first, so east-of-Greenwich timezones lose a
 * day: the date picker hands back local midnight, and in Dubai (UTC+4) that is
 * 20:00 the previous day once expressed as UTC. Every date sent to the API is
 * a calendar day, not an instant, so it has to be read off the local clock.
 */
export function toLocalDateString(value: Date | string): string {
  // A string coming back from the API is already a calendar day — whether it
  // is '2026-09-25' or '2026-09-25T00:00:00.000Z'. Re-parsing it into a Date
  // would re-interpret that day as an instant and shift it again, so the date
  // part is taken verbatim and the round trip stays lossless.
  if (typeof value === 'string') {
    const datePart = /^(\d{4}-\d{2}-\d{2})/.exec(value);
    if (datePart) {
      return datePart[1];
    }
  }

  const date = value instanceof Date ? value : new Date(value);

  if (isNaN(date.getTime())) {
    return '';
  }

  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');

  return `${year}-${month}-${day}`;
}
