import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { CommonService } from 'src/app/shared/services/common.service';
import { NzNotificationService } from 'ng-zorro-antd/notification';
import { NzModalService } from 'ng-zorro-antd/modal';

/** The journey steps drawn on the progress bar, per clay. */
const JOURNEY_STEPS: { [key: string]: string[] } = {
  terracotta: ['created', 'drying', 'firing', 'ready', 'collected'],
  ceramic: ['created', 'drying', 'firing', 'painting', 'ready', 'collected'],
};

const STATUS_LABELS: { [key: string]: string } = {
  created: 'Created',
  drying: 'Drying',
  firing: 'Firing',
  painting: 'Painting',
  delay: 'Delayed',
  ready: 'Ready for Collection',
  collected: 'Collected',
  discarded: 'Discarded',
};

/**
 * Booking statuses that mean the booking was confirmed and has not been
 * cancelled — 'confirmed' itself plus everything tracking moves it on to.
 */
const CONFIRMED_OR_LATER = ['confirmed', 'completed', 'collected'];

/** Which stored date belongs against each step. */
const STEP_DATE_FIELDS: { [key: string]: string } = {
  created: 'startedAt',
  drying: 'dryingAt',
  firing: 'firingAt',
  painting: 'paintingAt',
  ready: 'readyAt',
  collected: 'collectedAt',
};

@Component({
  selector: 'app-booking-detail',
  templateUrl: './booking-detail.component.html',
  styleUrls: ['./booking-detail.component.css']
})
export class BookingDetailComponent implements OnInit {

  booking: any;
  id!: string;

  /** Comma or newline separated while the admin types; split on submit. */
  itemCodeInput: string = '';
  delayNote: string = '';

  saving: boolean = false;

  get hasGiftDetails(): boolean {
    const gift = this.booking?.giftDetails;
    if (!gift) {
      return false;
    }
    return Object.values(gift).some(
      (value) => value !== null && value !== undefined && value !== ''
    );
  }

  constructor(
    private route: ActivatedRoute,
    private commonService: CommonService,
    private router: Router,
    private notification: NzNotificationService,
    private modal: NzModalService
  ) {}

  ngOnInit(): void {
    this.id = this.route.snapshot.paramMap.get('id')!;
    this.loadData();
  }

  loadData(): void {

    this.commonService.getDataById('/workshop/workshop-booking', this.id).subscribe({

      next: (response: any) => {

        if (response?.result) {
          this.booking = response.result;
          this.itemCodeInput = (this.tracking?.itemCodes || []).join(', ');
          this.buildJourneySteps();
        } else {
          this.notification.error('Error', 'Booking not found');
          this.router.navigate(['/admin/workshop-bookings']);
        }

      },

      error: () => {
        this.notification.error('Error', 'Failed to load booking');
        this.router.navigate(['/admin/workshop-bookings']);
      }

    });

  }

  /* ======================
   * ITEM TRACKING
   * ====================== */

  /**
   * Whether the tracking card is offered at all.
   *
   * Tracking belongs to a booking that is paid for and actually confirmed — a
   * pending or cancelled booking has no pieces in the studio to follow.
   *
   * `bookingStatus` does not stay on 'confirmed' once tracking is underway:
   * starting tracking moves it to 'completed' and collection moves it to
   * 'collected'. So the test is "has reached confirmed" rather than "is
   * confirmed" — a literal equality check would hide the card the moment the
   * admin completes the workshop, taking the journey, the stage actions and the
   * tracking link with it.
   */
  get canTrack(): boolean {
    return (
      this.booking?.paymentStatus === 'paid' &&
      CONFIRMED_OR_LATER.includes(this.booking?.bookingStatus)
    );
  }

  /** The server-computed tracking block: stored fields plus derived dates. */
  get summary(): any {
    return this.booking?.trackingSummary;
  }

  get tracking(): any {
    return this.summary?.isTracked ? this.summary : null;
  }

  /**
   * 'terracotta' | 'ceramic' | null — null means an Air-Dry booking, which the
   * customer takes home the same day and so has no journey to follow.
   */
  get clayCategory(): string | null {
    return this.summary?.clayCategory || null;
  }

  get clayLabel(): string {
    return this.clayCategory === 'ceramic' ? 'Ceramic Clay' : 'Terracotta Clay';
  }

  get isTrackable(): boolean {
    return !!this.clayCategory;
  }

  get isCollected(): boolean {
    return this.booking?.bookingStatus === 'collected';
  }

  /** True once the piece has finished its journey either way. */
  get isJourneyClosed(): boolean {
    return this.tracking?.status === 'collected' || this.tracking?.status === 'discarded';
  }

  statusLabel(status: string): string {
    return STATUS_LABELS[status] || status;
  }

  /** Every booking status the schema allows gets its own colour, not a catch-all. */
  bookingStatusColor(status: string): string {
    const colors: { [key: string]: string } = {
      confirmed: 'green',
      completed: 'blue',
      collected: 'green',
      cancelled: 'red',
      pending: 'orange',
    };
    return colors[status] || 'default';
  }

  trackingStatusColor(status: string): string {
    const colors: { [key: string]: string } = {
      created: 'blue',
      drying: 'cyan',
      firing: 'volcano',
      painting: 'purple',
      delay: 'orange',
      ready: 'green',
      collected: 'green',
      discarded: 'red',
    };
    return colors[status] || 'default';
  }

  /**
   * The steps drawn on the journey bar.
   *
   * Held as a field and rebuilt on load rather than computed in a getter.
   * `*ngFor` tracks its items by identity, so a getter handing back a fresh
   * array of fresh objects on every change-detection pass makes nz-steps
   * destroy and re-create its children each pass; nz-steps reacts to that by
   * queueing a microtask, which asks Angular for another pass, which rebuilds
   * the array again. The page never settles and the browser locks up.
   */
  journeySteps: { status: string; label: string; date: any }[] = [];

  private buildJourneySteps(): void {
    const steps = JOURNEY_STEPS[this.clayCategory || 'terracotta'] || [];
    const tracking = this.tracking;

    this.journeySteps = steps.map((status) => ({
      status,
      label: STATUS_LABELS[status],
      date: tracking ? tracking[STEP_DATE_FIELDS[status]] : null,
    }));
  }

  /**
   * Where the marker sits on the bar.
   *
   * A delayed piece still shows at Firing with the delay called out alongside —
   * the journey has not gone backwards, it is just taking longer. A discarded
   * piece stops at Ready, which is as far as it ever got.
   */
  get currentStepIndex(): number {
    const status = this.tracking?.status;
    if (!status) return -1;

    const position =
      status === 'delay' ? 'firing' : status === 'discarded' ? 'ready' : status;

    return this.journeySteps.findIndex((step) => step.status === position);
  }

  get stepsStatus(): 'error' | 'process' | 'finish' {
    if (this.tracking?.status === 'discarded') return 'error';
    if (this.tracking?.status === 'collected') return 'finish';
    return 'process';
  }

  /** Free text in, one clean code per entry out — the server re-checks this. */
  private parseItemCodes(): string[] {
    return this.itemCodeInput
      .split(/[\n,]/)
      .map((code) => code.trim().toUpperCase())
      .filter((code) => !!code);
  }

  private post(endpoint: string, body: any, successMessage: string): void {
    this.saving = true;

    this.commonService.postAction(endpoint, body).subscribe({
      next: () => {
        this.notification.success('Success', successMessage);
        this.saving = false;
        this.delayNote = '';
        this.loadData();
      },
      error: (err) => {
        this.notification.error('Error', err?.error?.message || 'Something went wrong');
        this.saving = false;
      },
    });
  }

  /**
   * "Workshop completed" — closes the booking, records the codes on the pieces
   * and mails the customer their tracking link, all in one action.
   */
  startTracking(): void {
    const itemCodes = this.parseItemCodes();

    if (!itemCodes.length) {
      this.notification.error('Item codes required', 'Add at least one item code before completing the workshop');
      return;
    }

    this.modal.confirm({
      nzTitle: 'Complete this workshop and start tracking?',
      nzContent: `${itemCodes.length} item code${itemCodes.length === 1 ? '' : 's'} will be saved and the tracking link emailed to ${this.booking?.customer?.email}.`,
      nzOkText: 'Complete & send link',
      nzOnOk: () =>
        this.post(
          `workshop/bookings/${this.id}/tracking/start`,
          { itemCodes },
          'Tracking started and the link has been emailed to the customer'
        ),
    });
  }

  saveItemCodes(): void {
    const itemCodes = this.parseItemCodes();

    if (!itemCodes.length) {
      this.notification.error('Item codes required', 'At least one item code is required');
      return;
    }

    this.post(
      `workshop/bookings/${this.id}/tracking/item-codes`,
      { itemCodes },
      'Item codes updated'
    );
  }

  /**
   * Ceramic only — terracotta is glazed in the same pass it is fired, so it has
   * no painting stage. Offered until the piece is ready, since painting closes
   * once the journey has moved past it.
   */
  get canOpenPainting(): boolean {
    return (
      this.clayCategory === 'ceramic' &&
      !!this.tracking &&
      this.tracking.status !== 'painting' &&
      this.tracking.status !== 'ready'
    );
  }

  markPainting(): void {
    this.modal.confirm({
      nzTitle: 'Open painting for this piece?',
      nzContent: `A "ready to paint" email goes to ${this.booking?.customer?.email} inviting them to book their painting session, and the journey moves to Painting.`,
      nzOkText: 'Open painting & email',
      nzOnOk: () =>
        this.post(
          `workshop/bookings/${this.id}/tracking/status`,
          { status: 'painting' },
          'Piece marked ready for painting — the invitation has been sent'
        ),
    });
  }

  markDelayed(): void {
    this.modal.confirm({
      nzTitle: 'Mark this piece as delayed?',
      nzContent: `A "taking a little longer" email goes to ${this.booking?.customer?.email} with the revised ready date, and the same note shows on their tracking page. The piece stops advancing on its own from here — mark it ready once the repair is done and the rest of the journey carries on as normal.`,
      nzOkText: 'Mark delayed & email',
      nzOnOk: () =>
        this.post(
          `workshop/bookings/${this.id}/tracking/status`,
          { status: 'delay', note: this.delayNote || undefined },
          'Piece marked as delayed'
        ),
    });
  }

  markReady(): void {
    this.modal.confirm({
      nzTitle: 'Mark this piece ready for collection?',
      nzContent: `A "ready to collect" email goes to ${this.booking?.customer?.email} with the item codes.`,
      nzOkText: 'Mark ready & email',
      nzOnOk: () =>
        this.post(
          `workshop/bookings/${this.id}/tracking/status`,
          { status: 'ready' },
          'Piece marked ready — the collection email has been sent'
        ),
    });
  }

  markTrackedCollected(): void {
    this.modal.confirm({
      nzTitle: 'Mark this piece as collected?',
      nzContent: 'This closes the booking. The customer has picked their piece up.',
      nzOkText: 'Mark collected',
      nzOnOk: () =>
        this.post(
          `workshop/bookings/${this.id}/tracking/status`,
          { status: 'collected' },
          'Piece marked as collected'
        ),
    });
  }

  markDiscarded(): void {
    this.modal.confirm({
      nzTitle: 'Discard this piece?',
      nzContent:
        'Use this only for a piece that was never collected. It happens on its own one month after the estimated collection date.',
      nzOkText: 'Discard',
      nzOkDanger: true,
      nzOnOk: () =>
        this.post(
          `workshop/bookings/${this.id}/tracking/status`,
          { status: 'discarded' },
          'Piece marked as discarded'
        ),
    });
  }

  /** Air-Dry bookings: nothing stays in the studio, so this is the whole flow. */
  markBookingCollected(): void {
    this.modal.confirm({
      nzTitle: 'Mark this booking as collected?',
      nzContent:
        'Air-Dry pieces go home with the customer on the day, so there is nothing to track.',
      nzOkText: 'Mark collected',
      nzOnOk: () =>
        this.post(`workshop/bookings/${this.id}/collected`, {}, 'Booking marked as collected'),
    });
  }

  copyTrackingLink(): void {
    const url = this.tracking?.trackingUrl;
    if (!url) return;

    navigator.clipboard?.writeText(url).then(
      () => this.notification.success('Copied', 'Tracking link copied to clipboard'),
      () => this.notification.error('Error', 'Could not copy the tracking link')
    );
  }
}
