import { Component, HostListener, OnInit } from '@angular/core';
import { AbstractControl, FormArray, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { NzNotificationService } from 'ng-zorro-antd/notification';
import { CategoryService } from 'src/app/shared/services/category.service';
import { FileUploadService } from 'src/app/shared/services/file-upload.service';
import { CommonService } from 'src/app/shared/services/common.service';
import { ActivatedRoute } from '@angular/router';
import { HasUnsavedChanges } from 'src/app/shared/guards/unsaved-changes.guard';
import { toLocalDateString } from 'src/app/shared/utils/date.util';
import { formatTime12, parseTimeString } from 'src/app/shared/utils/time.util';

/** Live state of one upload slot, keyed by the field it belongs to. */
interface UploadSlot {
  busy: boolean;
  percent: number;
  error: string | null;
}

/** One thing the admin still has to fix, addressed to where it lives. */
interface FormProblem {
  step: number;
  stepTitle: string;
  where: string;
  field: string;
}

@Component({
  selector: 'app-workshop-add',
  templateUrl: './workshop-add.component.html',
  styleUrls: ['./workshop-add.component.css']
})
export class WorkshopAddComponent implements OnInit, HasUnsavedChanges {

  workshopForm!: FormGroup;
  categories: any[] = [];
  clayTypes: any[] = [];

  isEditMode = false;
  workshopId!: string;
  isSubmitting = false;
  isLoading = false;
  loadFailed = false;

  /** Set once a save succeeds, so leaving afterwards asks nothing. */
  private savedCleanly = false;

  showHomepageToggle = false;

  /* ---- Wizard ---------------------------------------------------------- */

  currentStep = 0;

  readonly steps = [
    { title: 'Basics', caption: 'Name, category and copy' },
    { title: 'Media', caption: 'Banner, journey and gallery' },
    { title: 'Pricing', caption: 'Clay options and what is included' },
    { title: 'Schedule', caption: 'Slots, closures and extra detail' },
  ];

  /** Problems found on the last submit or step advance. */
  problems: FormProblem[] = [];
  showProblems = false;

  /* ---- Uploads --------------------------------------------------------- */

  uploads: { [key: string]: UploadSlot } = {};

  weekDays = [
    'Sunday',
    'Monday',
    'Tuesday',
    'Wednesday',
    'Thursday',
    'Friday',
    'Saturday'
  ];

  constructor(
    private fb: FormBuilder,
    private router: Router,
    private notification: NzNotificationService,
    private categoryService: CategoryService,
    private commonService: CommonService,
    private fileUploadService: FileUploadService,
    private route: ActivatedRoute,
  ) {}

  ngOnInit(): void {
    this.workshopId = this.route.snapshot.paramMap.get('id') || '';
    this.isEditMode = !!this.workshopId;
    this.initForm();
    this.listenCategoryChange();
    this.loadClayTypes();
    this.loadCategories();
  }

  initForm(): void {
    this.workshopForm = this.fb.group({
      title: ['', Validators.required],
      categoryId: ['', Validators.required],
      shortDescription: [''],
      description: ['', Validators.required],
      overview: [''],
      // Media now holds uploaded URLs — files are sent the moment they are picked.
      bannerImage: [''],
      journeyImage: this.fb.array([]),
      images: this.fb.array([]),
      defaultSlots: this.fb.array([]),
      options: this.fb.array([]),
      nonAvailabilityDates: [null],
      nonAvailabilityDays: this.fb.array(
        this.weekDays.map(() => this.fb.control(false))
      ),
      isActive: [true],
      showOnHomepage: [false],
      includes: this.fb.array([]),
      moreDetails: this.fb.array([])
    });
  }

  /* ================= LOAD (edit) ================= */

  loadCategories(): void {
    this.categoryService.getActiveCategories().subscribe({
      next: (res) => {
        this.categories = res?.result?.categories || [];
        if (this.isEditMode) {
          this.loadWorkshop();
        }
      },
      error: () => {
        // Previously this failure left the edit form blank and submittable,
        // which would overwrite a live workshop with empty values.
        this.notification.error('Error', 'Could not load categories');
        if (this.isEditMode) {
          this.loadFailed = true;
        }
      }
    });
  }

  loadClayTypes(): void {
    this.commonService.getAllData('clay-type/all').subscribe({
      next: (res) => (this.clayTypes = res?.result?.clayTypes || []),
      error: () => this.notification.error('Error', 'Could not load clay types')
    });
  }

  loadWorkshop(): void {
    this.isLoading = true;

    this.commonService.getDataById('/workshop', this.workshopId).subscribe({
      next: (res) => {
        const workshop = res?.result;

        if (!workshop) {
          this.isLoading = false;
          this.loadFailed = true;
          this.notification.error('Error', 'Workshop not found');
          return;
        }

        this.workshopForm.patchValue({
          title: workshop.title,
          categoryId: workshop.categoryId?._id || workshop.categoryId,
          shortDescription: workshop.shortDescription,
          description: workshop.description,
          overview: workshop.overview,
          isActive: workshop.isActive,
          showOnHomepage: workshop.showOnHomepage,
          nonAvailabilityDates: workshop.nonAvailabilityDates,
          bannerImage: workshop.bannerImage || ''
        });

        (workshop.journeyImage || []).forEach((url: string) =>
          this.journeyImages.push(this.fb.control(url))
        );

        (workshop.defaultSlots || []).forEach((slot: any) => {
          this.defaultSlots.push(
            this.fb.group({
              label: [slot.label, Validators.required],
              startTime: [parseTimeString(slot.startTime), Validators.required],
              endTime: [parseTimeString(slot.endTime), Validators.required],
              capacity: [slot.capacity]
            })
          );
        });

        (workshop.options || []).forEach((opt: any) => {
          this.options.push(
            this.buildOptionGroup({
              clayType: opt.clayTypeId,
              title: opt.title,
              price: opt.price,
              currency: opt.currency,
              priceDescription: opt.priceDescription,
              description: opt.description,
              inclusions: opt.inclusions || [],
              image: opt.image || '',
              clayTypeThumbnail: opt.clayTypethumbnailImage || '',
              clayTypeVideo: opt.clayTypeVideo || ''
            })
          );
        });

        (workshop.includes || []).forEach((inc: any) =>
          this.includesArray.push(
            this.fb.group({ title: [inc.title, Validators.required] })
          )
        );

        (workshop.images || []).forEach((img: any) =>
          this.imagesArray.push(
            this.fb.group({ image: [img.image], title: [img.title] })
          )
        );

        const dayControls = this.nonAvailabilityDays.controls;
        this.weekDays.forEach((day, i) => {
          if (workshop.nonAvailabilityDays?.includes(day)) {
            dayControls[i].setValue(true);
          }
        });

        (workshop.moreDetails || []).forEach((item: any) =>
          this.moreDetailsArray.push(
            this.fb.group({
              title: [item.title, Validators.required],
              icon: [item.icon || ''],
              description: [item.description]
            })
          )
        );

        // Loading is not the admin's own input, so it must not arm the guard.
        this.workshopForm.markAsPristine();
        this.isLoading = false;
      },
      error: () => {
        this.isLoading = false;
        this.loadFailed = true;
        this.notification.error('Error', 'Could not load this workshop');
      }
    });
  }

  /* ================= GETTERS ================= */

  get imagesArray(): FormArray {
    return this.workshopForm.get('images') as FormArray;
  }

  get journeyImages(): FormArray {
    return this.workshopForm.get('journeyImage') as FormArray;
  }

  get includesArray(): FormArray {
    return this.workshopForm.get('includes') as FormArray;
  }

  get defaultSlots(): FormArray {
    return this.workshopForm.get('defaultSlots') as FormArray;
  }

  get options(): FormArray {
    return this.workshopForm.get('options') as FormArray;
  }

  get nonAvailabilityDays(): FormArray {
    return this.workshopForm.get('nonAvailabilityDays') as FormArray;
  }

  get moreDetailsArray(): FormArray {
    return this.workshopForm.get('moreDetails') as FormArray;
  }

  get bannerUrl(): string {
    return this.workshopForm.get('bannerImage')?.value || '';
  }

  get nonAvailabilityDates(): Date[] {
    const value = this.workshopForm.get('nonAvailabilityDates')?.value;
    return Array.isArray(value) ? value : [];
  }

  getInclusions(optionIndex: number): FormArray {
    return this.options.at(optionIndex).get('inclusions') as FormArray;
  }

  /* ================= UNSAVED-CHANGES CONTRACT ================= */

  canLeave(): boolean {
    if (this.savedCleanly || this.isSubmitting) {
      return true;
    }
    return !this.workshopForm?.dirty;
  }

  unsavedChangesMessage(): string {
    return this.isEditMode
      ? 'This workshop has unsaved edits. Leave and discard them?'
      : 'This workshop has not been saved yet. Leave and discard it?';
  }

  @HostListener('window:beforeunload', ['$event'])
  onBeforeUnload(event: BeforeUnloadEvent): void {
    if (!this.canLeave()) {
      event.preventDefault();
      event.returnValue = true;
    }
  }

  /** Used by "Back to List" so the router guard is the only thing that asks. */
  backToList(): void {
    this.router.navigate(['/admin/workshops']);
  }

  /* ================= UPLOADS (on select) ================= */

  slot(key: string): UploadSlot {
    return this.uploads[key] || { busy: false, percent: 0, error: null };
  }

  get anyUploadBusy(): boolean {
    return Object.keys(this.uploads).some((k) => this.uploads[k].busy);
  }

  /**
   * Validates, uploads and reports as it goes. Resolves to the stored URLs.
   *
   * Uploading here rather than at submit means a rejected or oversized file is
   * reported against the field that caused it, while the admin is still looking
   * at that field — and submit is left as a single fast request.
   */
  private async upload(
    key: string,
    files: File[],
    allowVideo: boolean
  ): Promise<string[]> {
    this.uploads[key] = { busy: false, percent: 0, error: null };

    for (const file of files) {
      const check = allowVideo
        ? this.fileUploadService.validateMediaFile(file)
        : this.fileUploadService.validateImageFile(file);

      if (!check.valid) {
        this.uploads[key] = {
          busy: false,
          percent: 0,
          error: `${file.name} (${this.fileUploadService.formatSize(file.size)}) — ${check.error}`
        };
        return [];
      }
    }

    this.uploads[key] = { busy: true, percent: 0, error: null };

    try {
      const res = await this.fileUploadService
        .uploadFileService(files, 'workshops', false, (percent) => {
          this.uploads[key] = { busy: true, percent, error: null };
        })
        .toPromise();

      const urls: string[] = res?.result || [];

      if (!urls.length) {
        this.uploads[key] = {
          busy: false,
          percent: 0,
          error: 'Upload finished but returned no file. Please try again.'
        };
        return [];
      }

      this.uploads[key] = { busy: false, percent: 100, error: null };
      this.workshopForm.markAsDirty();
      return urls;

    } catch (err: any) {
      this.uploads[key] = {
        busy: false,
        percent: 0,
        error: err?.error?.message || 'Upload failed. Please try again.'
      };
      return [];
    }
  }

  private filesFrom(event: any): File[] {
    return Array.from(event?.target?.files || []) as File[];
  }

  /** Lets the same file be re-picked after a failed attempt. */
  private resetInput(event: any): void {
    if (event?.target) {
      event.target.value = '';
    }
  }

  async onBannerChange(event: any): Promise<void> {
    const files = this.filesFrom(event);
    this.resetInput(event);
    if (!files.length) return;

    const urls = await this.upload('banner', [files[0]], true);
    if (urls.length) {
      this.workshopForm.get('bannerImage')?.setValue(urls[0]);
    }
  }

  clearBanner(): void {
    this.workshopForm.get('bannerImage')?.setValue('');
    this.workshopForm.markAsDirty();
    delete this.uploads['banner'];
  }

  async onJourneyChange(event: any): Promise<void> {
    const files = this.filesFrom(event);
    this.resetInput(event);
    if (!files.length) return;

    const urls = await this.upload('journey', files, false);
    urls.forEach((url) => this.journeyImages.push(this.fb.control(url)));
  }

  removeJourneyImage(index: number): void {
    this.journeyImages.removeAt(index);
    this.workshopForm.markAsDirty();
  }

  async onImagesChange(event: any): Promise<void> {
    const files = this.filesFrom(event);
    this.resetInput(event);
    if (!files.length) return;

    const urls = await this.upload('images', files, false);
    urls.forEach((url) =>
      this.imagesArray.push(this.fb.group({ image: [url], title: [''] }))
    );
  }

  removeImage(index: number): void {
    this.imagesArray.removeAt(index);
    this.workshopForm.markAsDirty();
  }

  async onOptionImageChange(event: any, index: number): Promise<void> {
    const files = this.filesFrom(event);
    this.resetInput(event);
    if (!files.length) return;

    const urls = await this.upload(`option-image-${index}`, [files[0]], false);
    if (urls.length) {
      this.options.at(index).get('image')?.setValue(urls[0]);
    }
  }

  async onClayThumbnailChange(event: any, index: number): Promise<void> {
    const files = this.filesFrom(event);
    this.resetInput(event);
    if (!files.length) return;

    const urls = await this.upload(`option-thumb-${index}`, [files[0]], false);
    if (urls.length) {
      this.options.at(index).get('clayTypeThumbnail')?.setValue(urls[0]);
    }
  }

  async onClayVideoChange(event: any, index: number): Promise<void> {
    const files = this.filesFrom(event);
    this.resetInput(event);
    if (!files.length) return;

    const urls = await this.upload(`option-video-${index}`, [files[0]], true);
    if (urls.length) {
      this.options.at(index).get('clayTypeVideo')?.setValue(urls[0]);
    }
  }

  clearOptionAsset(index: number, field: string, key: string): void {
    this.options.at(index).get(field)?.setValue('');
    this.workshopForm.markAsDirty();
    delete this.uploads[`${key}-${index}`];
  }

  async onMoreDetailIconChange(event: any, index: number): Promise<void> {
    const files = this.filesFrom(event);
    this.resetInput(event);
    if (!files.length) return;

    const urls = await this.upload(`detail-icon-${index}`, [files[0]], false);
    if (urls.length) {
      this.moreDetailsArray.at(index).get('icon')?.setValue(urls[0]);
    }
  }

  isVideoUrl(url: string): boolean {
    return /\.(mp4|webm|mov|m4v)(\?|$)/i.test(url || '');
  }

  /* ================= ROWS ================= */

  addSlot(): void {
    this.defaultSlots.push(
      this.fb.group({
        label: ['', Validators.required],
        startTime: [null, Validators.required],
        endTime: [null, Validators.required],
        capacity: [12]
      })
    );
  }

  removeSlot(index: number): void {
    this.defaultSlots.removeAt(index);
  }

  private buildOptionGroup(seed: any = {}): FormGroup {
    const group = this.fb.group({
      clayType: [seed.clayType ?? null],
      title: [seed.title ?? '', Validators.required],
      price: [seed.price ?? null, Validators.required],
      currency: [seed.currency ?? 'AED'],
      priceDescription: [seed.priceDescription ?? ''],
      description: [seed.description ?? ''],
      inclusions: this.fb.array(
        (seed.inclusions || []).map((inc: string) =>
          this.fb.control(inc, Validators.required)
        )
      ),
      image: [seed.image ?? ''],
      clayTypeThumbnail: [seed.clayTypeThumbnail ?? ''],
      clayTypeVideo: [seed.clayTypeVideo ?? '']
    });

    // valueChanges rather than a template (ngModelChange): the reactive control
    // is the only thing guaranteed to emit for an nz-select.
    group.get('clayType')?.valueChanges.subscribe((clayId) => {
      const selectedClay = this.clayTypes.find(
        (c) => String(c._id) === String(clayId)
      );
      if (!selectedClay) return;

      const titleControl = group.get('title');
      // Only fill a blank title — overwriting discarded what the admin typed.
      if (titleControl && !String(titleControl.value || '').trim()) {
        titleControl.setValue(selectedClay.title);
      }
    });

    return group;
  }

  addOption(): void {
    this.options.push(this.buildOptionGroup());
  }

  removeOption(index: number): void {
    this.options.removeAt(index);
    delete this.uploads[`option-image-${index}`];
    delete this.uploads[`option-thumb-${index}`];
    delete this.uploads[`option-video-${index}`];
  }

  addInclusion(optionIndex: number): void {
    this.getInclusions(optionIndex).push(
      this.fb.control('', Validators.required)
    );
  }

  removeInclusion(optionIndex: number, inclusionIndex: number): void {
    this.getInclusions(optionIndex).removeAt(inclusionIndex);
  }

  addInclude(): void {
    this.includesArray.push(
      this.fb.group({ title: ['', Validators.required] })
    );
  }

  removeInclude(index: number): void {
    this.includesArray.removeAt(index);
  }

  addMoreDetail(): void {
    this.moreDetailsArray.push(
      this.fb.group({
        title: ['', Validators.required],
        icon: [''],
        description: ['']
      })
    );
  }

  removeMoreDetail(index: number): void {
    this.moreDetailsArray.removeAt(index);
    delete this.uploads[`detail-icon-${index}`];
  }

  removeDate(index: number): void {
    const dates = [...this.nonAvailabilityDates];
    dates.splice(index, 1);
    this.workshopForm.get('nonAvailabilityDates')?.setValue(
      dates.length ? dates : null
    );
  }

  listenCategoryChange(): void {
    this.workshopForm.get('categoryId')?.valueChanges.subscribe((categoryId) => {
      const selectedCategory = this.categories.find(
        (cat) => cat._id === categoryId
      );

      if (selectedCategory?.showOnHomepage === true) {
        this.showHomepageToggle = true;
      } else {
        this.showHomepageToggle = false;
        this.workshopForm.patchValue(
          { showOnHomepage: false },
          { emitEvent: false }
        );
      }
    });
  }

  /* ================= VALIDATION FEEDBACK ================= */

  isInvalid(controlName: string): boolean {
    const control = this.workshopForm.get(controlName);
    return !!(control && control.invalid && (control.dirty || control.touched));
  }

  /** Which step each top-level control belongs to, for the problem list. */
  private stepOf(controlName: string): number {
    switch (controlName) {
      case 'title':
      case 'categoryId':
      case 'shortDescription':
      case 'description':
      case 'overview':
      case 'isActive':
      case 'showOnHomepage':
        return 0;
      case 'bannerImage':
      case 'journeyImage':
      case 'images':
        return 1;
      case 'options':
      case 'includes':
        return 2;
      default:
        return 3;
    }
  }

  /**
   * Walks the form and names every unmet requirement in the admin's own terms.
   *
   * Several required controls live inside repeat blocks that carry no inline
   * error tip, so without this list a failed submit was silent.
   */
  private collectProblems(): FormProblem[] {
    const found: FormProblem[] = [];

    const push = (controlName: string, where: string, field: string) => {
      const step = this.stepOf(controlName);
      found.push({ step, stepTitle: this.steps[step].title, where, field });
    };

    const simple: Array<[string, string]> = [
      ['title', 'Workshop title'],
      ['categoryId', 'Category'],
      ['description', 'Description'],
    ];

    simple.forEach(([name, label]) => {
      if (this.workshopForm.get(name)?.invalid) {
        push(name, 'Basics', label);
      }
    });

    this.defaultSlots.controls.forEach((slot, i) => {
      const label = `Time slot ${i + 1}`;
      if (slot.get('label')?.invalid) push('defaultSlots', label, 'Label');
      if (slot.get('startTime')?.invalid) push('defaultSlots', label, 'Start time');
      if (slot.get('endTime')?.invalid) push('defaultSlots', label, 'End time');
    });

    this.options.controls.forEach((opt, i) => {
      const label = `Pricing option ${i + 1}`;
      if (opt.get('title')?.invalid) push('options', label, 'Title');
      if (opt.get('price')?.invalid) push('options', label, 'Price');

      (opt.get('inclusions') as FormArray).controls.forEach((inc, j) => {
        if (inc.invalid) push('options', label, `Inclusion ${j + 1}`);
      });
    });

    this.includesArray.controls.forEach((inc, i) => {
      if (inc.get('title')?.invalid) {
        push('includes', 'Workshop includes', `Item ${i + 1}`);
      }
    });

    this.moreDetailsArray.controls.forEach((item, i) => {
      if (item.get('title')?.invalid) {
        push('moreDetails', 'More details', `Item ${i + 1} title`);
      }
    });

    return found;
  }

  /** Steps that currently hold at least one problem, for the step indicator. */
  stepHasProblem(step: number): boolean {
    return this.showProblems && this.problems.some((p) => p.step === step);
  }

  goToStep(step: number): void {
    this.currentStep = Math.max(0, Math.min(this.steps.length - 1, step));
    this.scrollToTop();
  }

  next(): void {
    this.goToStep(this.currentStep + 1);
  }

  previous(): void {
    this.goToStep(this.currentStep - 1);
  }

  /** Jumps to the step holding a listed problem and focuses that region. */
  jumpTo(problem: FormProblem): void {
    this.goToStep(problem.step);
  }

  private scrollToTop(): void {
    if (typeof window !== 'undefined') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  }

  private focusFirstError(): void {
    if (typeof document === 'undefined') return;

    // Let the step switch render before hunting for the field.
    setTimeout(() => {
      const el = document.querySelector<HTMLElement>(
        '.ant-form-item-has-error input, .ant-form-item-has-error textarea, ' +
        '.ant-form-item-has-error .ant-select, .problem-summary'
      );
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        if (typeof el.focus === 'function') {
          el.focus({ preventScroll: true });
        }
      }
    }, 120);
  }

  /* ================= SUBMIT ================= */

  private buildPayload(): any {
    const value = this.workshopForm.value;

    const formattedSlots = (value.defaultSlots || []).map((slot: any) => ({
      ...slot,
      startTime: formatTime12(slot.startTime),
      endTime: formatTime12(slot.endTime)
    }));

    const selectedDays = (value.nonAvailabilityDays || [])
      .map((checked: boolean, i: number) => (checked ? this.weekDays[i] : null))
      .filter((v: string | null) => v !== null);

    const formattedDates = this.nonAvailabilityDates.map((d) =>
      toLocalDateString(d)
    );

    const formattedOptions = (value.options || []).map((opt: any) => ({
      clayTypeId: opt.clayType,
      title: opt.title,
      price: opt.price,
      currency: opt.currency,
      priceDescription: opt.priceDescription,
      description: opt.description,
      inclusions: opt.inclusions,
      image: opt.image || '',
      clayTypethumbnailImage: opt.clayTypeThumbnail || '',
      clayTypeVideo: opt.clayTypeVideo || ''
    }));

    const formattedMoreDetails = (value.moreDetails || []).map((item: any) => ({
      title: item.title,
      icon: item.icon || '',
      description: item.description
    }));

    const payload: any = {
      title: value.title,
      categoryId: value.categoryId,
      shortDescription: value.shortDescription,
      description: value.description,
      overview: value.overview,
      isActive: value.isActive,
      showOnHomepage: value.showOnHomepage,
      includes: value.includes,
      bannerImage: value.bannerImage || '',
      journeyImage: value.journeyImage || [],
      images: (value.images || []).map((img: any) => ({
        image: img.image,
        title: img.title
      })),
      options: formattedOptions,
      defaultSlots: formattedSlots,
      nonAvailabilityDays: selectedDays,
      nonAvailabilityDates: formattedDates,
      moreDetails: formattedMoreDetails
    };

    if (!this.showHomepageToggle) {
      delete payload.showOnHomepage;
    }

    return payload;
  }

  submitForm(): void {
    if (this.isSubmitting) {
      return;
    }

    if (this.anyUploadBusy) {
      this.notification.info('Please wait', 'An upload is still finishing.');
      return;
    }

    this.problems = this.collectProblems();

    if (this.problems.length) {
      this.showProblems = true;
      this.workshopForm.markAllAsTouched();
      this.goToStep(this.problems[0].step);
      this.focusFirstError();
      return;
    }

    this.showProblems = false;
    this.isSubmitting = true;

    const payload = this.buildPayload();

    const request = this.isEditMode
      ? this.commonService.updateData('/workshop', this.workshopId, payload)
      : this.commonService.addData('workshop', payload);

    request.subscribe({
      next: () => {
        this.isSubmitting = false;
        this.savedCleanly = true;
        this.workshopForm.markAsPristine();
        this.notification.success(
          'Success',
          this.isEditMode
            ? 'Workshop updated successfully'
            : 'Workshop created successfully'
        );
        // Both paths now land back on the list; edit used to sit on the form.
        this.router.navigate(['/admin/workshops']);
      },
      error: (err) => {
        this.isSubmitting = false;
        this.notification.error(
          'Error',
          err?.error?.message ||
            (this.isEditMode
              ? 'Failed to update workshop'
              : 'Failed to create workshop')
        );
      }
    });
  }
}
