/**
 * Clock-time helpers for the "9:30 AM" strings the API stores.
 *
 * Kept in one place because the parsing half is easy to get wrong: see
 * parseTimeString for why the obvious `new Date(...)` approach cannot be used.
 */

/**
 * Formats a Date as "9:30 AM".
 *
 * Built by hand rather than via toLocaleTimeString, whose recent ICU versions
 * emit a narrow no-break space (U+202F) before AM/PM that no string comparison
 * on the API side expects.
 */
export function formatTime12(value: Date | string): string {
  if (!value) {
    return '';
  }

  const date = value instanceof Date ? value : new Date(value);
  if (isNaN(date.getTime())) {
    return '';
  }

  const minutes = String(date.getMinutes()).padStart(2, '0');
  const suffix = date.getHours() >= 12 ? 'PM' : 'AM';
  const hours = date.getHours() % 12 || 12;

  return `${hours}:${minutes} ${suffix}`;
}

/**
 * Reads "9:30 AM" / "09:30 pm" back into a Date on 1 Jan 1970.
 *
 * `new Date('1970-01-01 9:30 AM')` parses only on V8 — Safari and Firefox
 * return Invalid Date, which blanked every time field when editing. The regex
 * also tolerates the narrow no-break space some formatters produce.
 */
export function parseTimeString(value: string): Date | null {
  if (!value) {
    return null;
  }

  const match = /^\s*(\d{1,2}):(\d{2})(?:[\s  ]*)([AaPp])?\.?[Mm]?\.?\s*$/.exec(value);
  if (!match) {
    return null;
  }

  let hours = Number(match[1]);
  const minutes = Number(match[2]);
  const meridiem = match[3] ? match[3].toUpperCase() : '';

  if (minutes > 59 || hours > 23) {
    return null;
  }

  if (meridiem === 'P' && hours < 12) {
    hours += 12;
  }
  if (meridiem === 'A' && hours === 12) {
    hours = 0;
  }

  const date = new Date(1970, 0, 1, hours, minutes, 0, 0);
  return isNaN(date.getTime()) ? null : date;
}

/** Minutes since midnight, for comparing two clock times. */
export function minutesOfDay(value: Date | string): number {
  const date = typeof value === 'string' ? parseTimeString(value) : value;
  if (!date || isNaN(date.getTime())) {
    return -1;
  }
  return date.getHours() * 60 + date.getMinutes();
}
