import { Component, OnInit } from '@angular/core';
import { NzMessageService } from 'ng-zorro-antd/message';
import { NzModalService } from 'ng-zorro-antd/modal';
import { CommonService } from 'src/app/shared/services/common.service';

@Component({
  selector: 'app-booking-list',
  templateUrl: './booking-list.component.html',
  styleUrls: ['./booking-list.component.css']
})

export class BookingListComponent implements OnInit {

  bookingList: any[] = [];

  pageIndex: number = 1;
  pageSize: number = 10;
  total: number = 0;

  searchInput: string = '';
  bookingStatus: string = 'All';
  /** 'All', 'none' for untracked bookings, or one tracking status. */
  trackingStatus: string = 'All';
  paymentStatus: string = 'All';
  dateRange: Date[] = [];

  loading: boolean = false;
  deleting: boolean = false;

  // Confirmed bookings are real reservations — they are never selectable and
  // the backend rejects them too, so this is only about hiding the checkbox.
  checkedIds = new Set<string>();
  allChecked: boolean = false;
  indeterminate: boolean = false;

  constructor(
    private commonService: CommonService,
    private modal: NzModalService,
    private message: NzMessageService,
  ) {}

  ngOnInit(): void {
    this.fetchBookings();
  }

  private buildFilters(): any {

    const filters: any = {
      search: this.searchInput || undefined,
      bookingStatus: this.bookingStatus !== 'All' ? this.bookingStatus : undefined,
      paymentStatus: this.paymentStatus !== 'All' ? this.paymentStatus : undefined,
      trackingStatus: this.trackingStatus !== 'All' ? this.trackingStatus : undefined,
    };

    if (this.dateRange.length === 2) {
      filters.startDate = this.dateRange[0].toISOString().split('T')[0];
      filters.endDate = this.dateRange[1].toISOString().split('T')[0];
    }

    return filters;
  }

  fetchBookings(): void {

    this.loading = true;

    this.commonService
      .getData(this.pageIndex, this.pageSize, 'workshop/bookings/all', this.buildFilters())
      .subscribe({
        next: (res: any) => {
          this.bookingList = res.result.data;
          this.total = res.result.totalCount;
          this.clearSelection();
          this.loading = false;
        },
        error: (err) => {
          console.error('Error fetching bookings:', err);
          this.loading = false;
        },
      });
  }

  search(): void {
    this.pageIndex = 1;
    this.fetchBookings();
  }

  bookingStatusChange(value: string): void {
    this.bookingStatus = value;
    this.pageIndex = 1;
    this.fetchBookings();
  }

  trackingStatusChange(value: string): void {
    this.trackingStatus = value;
    this.pageIndex = 1;
    this.fetchBookings();
  }

  paymentStatusChange(value: string): void {
    this.paymentStatus = value;
    this.pageIndex = 1;
    this.fetchBookings();
  }

  onDateRangeChange(): void {
    this.pageIndex = 1;
    this.fetchBookings();
  }

  onPageChange(page: number): void {
    this.pageIndex = page;
    this.fetchBookings();
  }

  /* Presentation helpers
   *
   * Kept in the component rather than as template ternaries so every status the
   * schema allows has an explicit colour, instead of silently falling into a
   * catch-all branch when a new one is added.
   */

  get rangeEnd(): number {
    return Math.min(this.pageIndex * this.pageSize, this.total);
  }

  statusColor(status: string): string {
    const colors: { [key: string]: string } = {
      confirmed: 'green',
      completed: 'blue',
      collected: 'green',
      cancelled: 'red',
      pending: 'orange',
    };
    return colors[status] || 'default';
  }

  trackingColor(status: string): string {
    const colors: { [key: string]: string } = {
      created: 'blue',
      drying: 'cyan',
      firing: 'volcano',
      painting: 'purple',
      delay: 'orange',
      ready: 'green',
      collected: 'green',
      discarded: 'red',
    };
    return colors[status] || 'default';
  }

  trackingLabel(status: string): string {
    const labels: { [key: string]: string } = {
      created: 'Created',
      drying: 'Drying',
      firing: 'Firing',
      painting: 'Painting',
      delay: 'Delayed',
      ready: 'Ready',
      collected: 'Collected',
      discarded: 'Discarded',
    };
    return labels[status] || status;
  }

  /**
   * The clay a booking would be tracked as, for rows that have no journey yet.
   *
   * Mirrors the backend's rule so the list can say "Terracotta, not started"
   * rather than a bare dash; Air-Dry bookings return '' and read as
   * "Not applicable".
   */
  trackableClayLabel(item: any): string {
    const titles = (item?.items || [])
      .map((entry: any) => (entry.optionTitle || '').toLowerCase())
      .join(' ');

    if (titles.includes('ceramic')) return 'Ceramic — not started';
    if (titles.includes('terracotta')) return 'Terracotta — not started';

    return '';
  }

  paymentColor(status: string): string {
    const colors: { [key: string]: string } = {
      paid: 'green',
      failed: 'red',
      refunded: 'purple',
      pending: 'orange',
    };
    return colors[status] || 'default';
  }

  typeColor(type: string): string {
    const colors: { [key: string]: string } = {
      gift: 'magenta',
      pottery: 'cyan',
      events: 'geekblue',
    };
    return colors[type] || 'default';
  }

  giftColor(status: string): string {
    const colors: { [key: string]: string } = {
      redeemed: 'green',
      completed: 'blue',
      pending: 'orange',
    };
    return colors[status] || 'default';
  }

  /** Package names booked, joined for display — bookings can hold several. */
  optionTitles(item: any): string {
    const titles = (item?.items || [])
      .map((entry: any) => (entry.optionTitle || '').trim())
      .filter((title: string) => !!title);

    return titles.length ? titles.join(', ') : '—';
  }

  /** "2 adults, 1 child" — only the parts the booking actually carries. */
  guestBreakdown(item: any): string {
    const totals = (item?.items || []).reduce(
      (acc: any, entry: any) => ({
        adult: acc.adult + (entry.adult || 0),
        child: acc.child + (entry.child || 0),
      }),
      { adult: 0, child: 0 },
    );

    const parts: string[] = [];
    if (totals.adult) parts.push(`${totals.adult} adult${totals.adult === 1 ? '' : 's'}`);
    if (totals.child) parts.push(`${totals.child} child${totals.child === 1 ? '' : 'ren'}`);

    return parts.join(', ');
  }

  /* Selection */

  /**
   * Mirrors the backend guard so the checkbox never offers something the server
   * would refuse: confirmed and collected bookings are real, and a booking with
   * a live tracking journey has a link already sitting in a customer's inbox.
   */
  isDeletable(item: any): boolean {
    return (
      item.bookingStatus !== 'confirmed' &&
      item.bookingStatus !== 'collected' &&
      !item.tracking?.status
    );
  }

  private get deletableOnPage(): any[] {
    return this.bookingList.filter((item) => this.isDeletable(item));
  }

  private clearSelection(): void {
    this.checkedIds.clear();
    this.refreshCheckedState();
  }

  private refreshCheckedState(): void {
    const selectable = this.deletableOnPage;
    this.allChecked =
      selectable.length > 0 && selectable.every((item) => this.checkedIds.has(item._id));
    this.indeterminate =
      selectable.some((item) => this.checkedIds.has(item._id)) && !this.allChecked;
  }

  onItemChecked(id: string, checked: boolean): void {
    if (checked) {
      this.checkedIds.add(id);
    } else {
      this.checkedIds.delete(id);
    }
    this.refreshCheckedState();
  }

  onAllChecked(checked: boolean): void {
    this.deletableOnPage.forEach((item) =>
      checked ? this.checkedIds.add(item._id) : this.checkedIds.delete(item._id),
    );
    this.refreshCheckedState();
  }

  /* Deletion */

  deleteBooking(item: any): void {
    this.modal.confirm({
      nzTitle: 'Remove this booking?',
      nzContent: `Booking ${item.bookingNumber} will be removed from the list.`,
      nzOkText: 'Remove',
      nzOkDanger: true,
      nzOnOk: () => this.runDelete({ ids: [item._id] }),
    });
  }

  deleteSelected(): void {
    const ids = Array.from(this.checkedIds);
    if (!ids.length) return;

    this.modal.confirm({
      nzTitle: `Remove ${ids.length} selected booking${ids.length === 1 ? '' : 's'}?`,
      nzContent: 'Confirmed, collected and tracked bookings are never removed.',
      nzOkText: 'Remove',
      nzOkDanger: true,
      nzOnOk: () => this.runDelete({ ids }),
    });
  }

  /**
   * Removes every test / failed / abandoned booking matching the filters that
   * are active right now — not just the rows on this page. The count is read
   * back from the server first so the dialog states exactly what will go.
   */
  deleteAllMatching(): void {
    const filters = this.buildFilters();

    // page/limit are appended by getData and ignored by the count endpoint.
    this.commonService
      .getData(1, 1, 'workshop/bookings/deletable-count', filters)
      .subscribe({
        next: (res: any) => {
          const count = res.result.deletableCount;

          if (!count) {
            this.message.info('There are no removable bookings for the current filters');
            return;
          }

          this.modal.confirm({
            nzTitle: `Remove ${count} booking${count === 1 ? '' : 's'}?`,
            nzContent:
              'This removes every pending, cancelled and failed booking matching the current filters. Confirmed, collected and tracked bookings are kept.',
            nzOkText: 'Remove all',
            nzOkDanger: true,
            nzOnOk: () => this.runDelete(filters),
          });
        },
        error: (err) => {
          this.message.error(err?.error?.message || 'Could not check removable bookings');
        },
      });
  }

  private runDelete(payload: any): Promise<void> {
    this.deleting = true;

    return new Promise((resolve) => {
      this.commonService.postAction('workshop/bookings/delete', payload).subscribe({
        next: (res: any) => {
          this.message.success(res.message || 'Bookings removed successfully');
          this.deleting = false;

          // The page the admin is on can end up past the end of the list once
          // its rows are gone — a filter-wide delete almost always does.
          if (!payload.ids) {
            this.pageIndex = 1;
          } else if (payload.ids.length === this.bookingList.length && this.pageIndex > 1) {
            this.pageIndex = this.pageIndex - 1;
          }

          this.fetchBookings();
          resolve();
        },
        error: (err) => {
          this.message.error(err?.error?.message || 'Delete failed');
          this.deleting = false;
          resolve();
        },
      });
    });
  }
}
